class CurrencyConverter:
    DEFAULT_USD_RATE = 1.0
    DEFAULT_EUR_RATE = 0.85
    DEFAULT_GBP_RATE = 0.72
    DEFAULT_JPY_RATE = 110.15
    DEFAULT_CAD_RATE = 1.23
    DEFAULT_AUD_RATE = 1.34
    DEFAULT_CNY_RATE = 6.40

    def __init__(self):
        self.rates = {
            'USD': self.DEFAULT_USD_RATE,
            'EUR': self.DEFAULT_EUR_RATE,
            'GBP': self.DEFAULT_GBP_RATE,
            'JPY': self.DEFAULT_JPY_RATE,
            'CAD': self.DEFAULT_CAD_RATE,
            'AUD': self.DEFAULT_AUD_RATE,
            'CNY': self.DEFAULT_CNY_RATE,
        }

    def convert(self, amount, from_currency, to_currency):
        if from_currency == to_currency:
            return amount

        if not self._is_valid_currency(from_currency) or not self._is_valid_currency(to_currency):
            return False

        converted_amount = self._calculate_conversion(amount, from_currency, to_currency)
        return converted_amount

    def _is_valid_currency(self, currency):
        return currency in self.rates

    def _calculate_conversion(self, amount, from_currency, to_currency):
        from_rate = self.rates[from_currency]
        to_rate = self.rates[to_currency]
        return (amount / from_rate) * to_rate

    def get_supported_currencies(self):
        return list(self.rates.keys())

    def add_currency_rate(self, currency, rate):
        if currency in self.rates:
            return False
        self.rates[currency] = rate

    def update_currency_rate(self, currency, new_rate):
        if currency not in self.rates:
            return False
        self.rates[currency] = new_rate
